const SocialFeature={id:"social",name:"Create Social Post",icon:"campaign",mediaFile:null,appointmentId:null,drafts:null,async render(e={}){const a=Number(e.appointmentId||e.id),t=Number.isInteger(a)&&a>0?await DB.getAppointment(a):null;if(!t||"fitting"!==t.type)return`<div class="fade-in">${App.renderTopHeader({title:"Social post",showBack:!0,backHref:"appointments"})}<div class="empty-state"><span class="material-symbols-rounded">photo_library</span><div>Open a fitting visit to create a post.</div></div></div>`;this.appointmentId=t.id,this.mediaFile=null,this.drafts=t.socialDrafts||null;const s=!!t.socialMediaConsentAt;return`<div class="fade-in">\n      ${App.renderTopHeader({title:"Create Social Post",showBack:!0,backHref:"appointments"})}\n      <div class="p-md">\n        <div class="card mb-md">\n          <div class="flex items-start gap-sm"><span class="material-symbols-rounded text-brand">auto_awesome</span><div><div class="fw-700">Turn today’s craftsmanship into a post</div><div class="fs-13 text-secondary mt-4 lh-145">Add the finished result, confirm the customer is comfortable with sharing it, and Beelo will prepare three editable captions. Nothing is published automatically.</div></div></div>\n        </div>\n\n        <div class="card mb-md">\n          <div class="fw-700 mb-sm">1. Permission first</div>\n          <label class="flex items-start gap-sm mb-sm"><input type="checkbox" id="social-consent" ${s?"checked":""}><span><strong>The customer has agreed</strong> that this finished-room photo or video may be used on my business social media.</span></label>\n          <div class="hint">Ask clearly before taking or sharing content. This permission is recorded against the fitting and can be withdrawn.</div>\n          ${s?'<button class="btn btn-ghost btn-sm mt-sm text-danger" data-action="SocialFeature.withdrawConsent">Withdraw recorded permission</button>':""}\n        </div>\n\n        <div class="card mb-md">\n          <div class="fw-700 mb-sm">2. Choose the finished result</div>\n          <button class="btn btn-outline btn-block" data-file="social-media-input"><span class="material-symbols-rounded">add_photo_alternate</span>Choose photo or short video</button>\n          <input type="file" id="social-media-input" accept="image/*,video/*" style="display:none" data-action="SocialFeature.selectMedia" data-args='["__event__"]'>\n          <div id="social-media-preview" class="fs-13 text-secondary mt-sm">No media selected.</div>\n          <div class="alert alert-warning mt-sm" role="note"><strong>Privacy check:</strong> avoid faces or children without separate permission, house numbers, paperwork, screens, family photos and identifying reflections.</div>\n          <label class="flex items-start gap-sm mt-sm"><input type="checkbox" id="social-privacy"><span>I have checked the full photo/video and no private or identifying details are visible.</span></label>\n        </div>\n\n        <div class="card mb-md">\n          <div class="fw-700 mb-sm">3. What made this job special?</div>\n          <div class="form-group"><label for="social-room">Room</label><input class="input" id="social-room" maxlength="60" placeholder="e.g. living room"></div>\n          <div class="form-group"><label for="social-product">Blind or curtain style</label><input class="input" id="social-product" maxlength="80" placeholder="e.g. warm-neutral Roman blinds"></div>\n          <div class="form-group"><label for="social-benefit">What improved?</label><input class="input" id="social-benefit" maxlength="120" placeholder="e.g. privacy without losing natural light"></div>\n          <div class="form-group"><label for="social-area">Local area only <span class="text-tertiary fw-400">— optional</span></label><input class="input" id="social-area" maxlength="50" placeholder="e.g. Stockport"><div class="hint">Never enter the customer’s street or full address.</div></div>\n          <button class="btn btn-primary btn-block" data-action="SocialFeature.generate"><span class="material-symbols-rounded">auto_awesome</span>Create three post options</button>\n        </div>\n\n        <div id="social-results">${this.drafts?this.renderDrafts(this.drafts):""}</div>\n      </div>\n    </div>`},selectMedia(e){const a=e?.target?.files?.[0];if(e?.target&&(e.target.value=""),!a)return;if(!/^(image|video)\//.test(a.type||""))return Toast.show("Choose a photo or video","warning");if(a.size>104857600)return Toast.show("Choose a file smaller than 100 MB","warning");this.mediaFile=a;const t=document.getElementById("social-media-preview");t&&(t.innerHTML=`<span class="material-symbols-rounded fs-18 align-middle">${a.type.startsWith("video/")?"videocam":"photo"}</span> ${Utils.escapeHtml(a.name||"Selected media")} · ${Math.max(1,Math.round(a.size/1024/1024))} MB`)},values(){const e=e=>(document.getElementById(e)?.value||"").trim();return{room:e("social-room"),product:e("social-product"),benefit:e("social-benefit"),area:e("social-area")}},fallbackDrafts(e){const a=[e.product||"made-to-measure window dressings",e.room?`for this ${e.room}`:""].filter(Boolean).join(" "),t=e.benefit?` The result brings ${e.benefit}.`:"",s=e.area?` in ${e.area}`:"";return{warm:`A lovely finish to this recent project${s}. We fitted ${a}.${t} It’s always rewarding to see a room come together. Message me if you’re planning something similar.`,professional:`Recently completed${s}: ${a}.${t} Designed, measured and fitted with care for a clean, made-to-measure finish. Get in touch to arrange a home consultation.`,short:`A fresh made-to-measure finish${s}. ${e.product||"Beautiful new window dressings"}, fitted with care. Message me to discuss your windows.`,hashtags:["#MadeToMeasure","#WindowDressings","#Blinds",...e.area?[`#${e.area.replace(/[^A-Za-z0-9]/g,"")}`]:[]]}},async generate(){if(!document.getElementById("social-consent")?.checked)return Toast.show("Confirm the customer has agreed first","warning");if(!this.mediaFile)return Toast.show("Choose a finished photo or video first","warning");if(!document.getElementById("social-privacy")?.checked)return Toast.show("Complete the privacy check first","warning");const e=this.values();if(!e.product&&!e.room&&!e.benefit)return Toast.show("Add one detail about the finished job","warning");let a=this.fallbackDrafts(e);if("undefined"!=typeof AIService&&AIService.isEnabled()&&"function"==typeof AIService.createSocialPosts){const t=await AIService.createSocialPosts(e);t.ok?a=t.drafts:Toast.show("Using polished offline captions — AI is unavailable","info")}this.drafts=a;try{await DB.updateAppointment(this.appointmentId,{socialMediaConsentAt:(new Date).toISOString(),socialMediaConsentMethod:"advisor_confirmed",socialDrafts:a})}catch(e){console.warn("Could not persist social draft",e)}const t=document.getElementById("social-results");t&&(t.innerHTML=this.renderDrafts(a)),t?.scrollIntoView({behavior:"smooth",block:"start"}),Toast.show("Three editable options are ready","success")},async withdrawConsent(){this.appointmentId&&(await DB.updateAppointment(this.appointmentId,{socialMediaConsentAt:null,socialMediaConsentMethod:null,socialDrafts:null}),this.drafts=null,this.mediaFile=null,Toast.show("Social sharing permission withdrawn","success"),App.navigate("appointments",{id:this.appointmentId}))},renderDrafts(e){const a=Array.isArray(e.hashtags)?e.hashtags.join(" "):"";return`<div class="card mb-md"><div class="fw-700 mb-sm">4. Choose, edit and share</div><div class="hint mb-md">You remain in control. Check every claim before sharing.</div>${[["warm","Warm and personal"],["professional","Professional and polished"],["short","Short and local"]].map(([a,t])=>`<div class="form-group"><label for="social-draft-${a}">${t}</label><textarea class="textarea" id="social-draft-${a}" rows="6">${Utils.escapeHtml(e[a]||"")}</textarea><button class="btn btn-outline btn-sm btn-block mt-sm" data-action="SocialFeature.share" data-args='${JSON.stringify([a])}'><span class="material-symbols-rounded">ios_share</span>Share this version</button></div>`).join("")}<div class="form-group"><label for="social-hashtags">Suggested hashtags</label><textarea class="textarea" id="social-hashtags" rows="2">${Utils.escapeHtml(a)}</textarea></div></div>`},async share(e){const a=[(document.getElementById(`social-draft-${e}`)?.value||"").trim(),(document.getElementById("social-hashtags")?.value||"").trim()].filter(Boolean).join("\n\n");if(!a)return Toast.show("Add a caption first","warning");const t=this.mediaFile?[this.mediaFile]:[];try{if(navigator.share&&(!t.length||!navigator.canShare||navigator.canShare({files:t})))return void await navigator.share({text:a,files:t})}catch(e){if("AbortError"===e?.name)return}try{await navigator.clipboard.writeText(a),Toast.show("Caption copied — attach the selected media in your social app","success")}catch(e){Toast.show("Could not open sharing on this device","error")}}};App.registerFeature(SocialFeature);
